const page$ = pageWindow.$;
// GM_storage key（使用 Tampermonkey 的持久化存储，不受网站 logout 影响）
const PREBILLING_CONFIG_KEY = "hha_prebilling_config";
// 默认 Coordinator IDs（向后兼容：Tao Yang）
const DEFAULT_COORDINATOR_IDS = ["75207"];
