        const location = locationIdx >= 0 ? cells[locationIdx]?.textContent?.trim() ?? "" : "";
        const branch = branchIdx >= 0 ? cells[branchIdx]?.textContent?.trim() ?? "" : "";
        const disciplines = disciplinesIdx >= 0
