        menu.style.left = `${rect.left - 150}px`;
        // Click handlers
        menu.querySelectorAll(".action-menu-item").forEach((menuItem) => {
            menuItem.addEventListener("click", () => {
                const action = menuItem.dataset.action;
                this.handleAction(action, item);
                menu.remove();
            });
        });
